package typeinfo

// PreserveAdaptiveEncoding returns the fresh TypeInfo with its storage encoding pinned to the
// existing TypeInfo's encoding, when both represent the same type family. This prevents a
// freshly-constructed TypeInfo (e.g. one produced while altering a table) from silently adopting
// the global adaptive-encoding default when the column was originally persisted under a legacy
// address encoding.
//
// It acts as a no-op (returning fresh unchanged) when existing is nil, when the two TypeInfos
// belong to different type families (e.g. VARCHAR to TEXT, or Point to LineString), or when the
// type family does not use variable adaptive encoding (e.g. integer types). When fresh is nil it
// returns nil.
//
// Only the storage encoding is copied from existing; the SQL type semantics of fresh (character
// length, collation, SRID, etc.) are left untouched. Covered type families are string/text
// (blobStringType), binary/blob (varBinaryType), JSON (jsonType), and every concrete geometry type
// (pointType, linestringType, polygonType, multipointType, multilinestringType, multipolygonType,
// geomcollType, geometryType).
func PreserveAdaptiveEncoding(existing TypeInfo, fresh TypeInfo) TypeInfo {
	if existing == nil {
		return fresh
	}
	if fresh == nil {
		return nil
	}

	// Only pin the encoding when existing and fresh are the same concrete type. Different concrete
	// types imply either a different type family (VARCHAR vs TEXT, Point vs LineString) or a family
	// that does not participate in adaptive encoding, both of which are left unchanged.
	switch f := fresh.(type) {
	case *blobStringType:
		if e, ok := existing.(*blobStringType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *varBinaryType:
		if e, ok := existing.(*varBinaryType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *jsonType:
		if e, ok := existing.(*jsonType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *pointType:
		if e, ok := existing.(*pointType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *linestringType:
		if e, ok := existing.(*linestringType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *polygonType:
		if e, ok := existing.(*polygonType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *multipointType:
		if e, ok := existing.(*multipointType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *multilinestringType:
		if e, ok := existing.(*multilinestringType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *multipolygonType:
		if e, ok := existing.(*multipolygonType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *geomcollType:
		if e, ok := existing.(*geomcollType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *geometryType:
		if e, ok := existing.(*geometryType); ok {
			return f.WithEncoding(e.Encoding())
		}
	}

	return fresh
}
