import (
	"testing"

	gmstypes "github.com/dolthub/go-mysql-server/sql/types"

	"github.com/dolthub/dolt/go/store/val"
)

func TestScratchPreserve(t *testing.T) {
	old := UseAdaptiveEncoding
	UseAdaptiveEncoding = true
	defer func() { UseAdaptiveEncoding = old }()

	// nil existing -> fresh unchanged
	fresh := TextType
	if PreserveAdaptiveEncoding(nil, fresh) != fresh {
		t.Fatal("nil existing")
	}
	// nil fresh -> nil
	if PreserveAdaptiveEncoding(TextType, nil) != nil {
		t.Fatal("nil fresh")
	}

	// string family, legacy addr enc, widening TEXT->LONGTEXT
	existing := (&blobStringType{sqlStringType: gmstypes.Text}).WithEncoding(val.StringAddrEnc)
	freshLong := &blobStringType{sqlStringType: gmstypes.LongText}
	got := PreserveAdaptiveEncoding(existing, freshLong)
	if got.Encoding() != val.StringAddrEnc {
		t.Fatalf("string enc: got %v", got.Encoding())
	}
	if got.ToSqlType().(gmstypes.StringType).MaxCharacterLength() != gmstypes.LongText.MaxCharacterLength() {
		t.Fatal("string sql semantics changed")
	}

	// blob family
	eb := (&varBinaryType{sqlBinaryType: gmstypes.Blob}).WithEncoding(val.BytesAddrEnc)
	if PreserveAdaptiveEncoding(eb, &varBinaryType{sqlBinaryType: gmstypes.LongBlob}).Encoding() != val.BytesAddrEnc {
		t.Fatal("blob enc")
	}

	// json
	ej := (&jsonType{}).WithEncoding(val.JSONAddrEnc)
	if PreserveAdaptiveEncoding(ej, &jsonType{}).Encoding() != val.JSONAddrEnc {
		t.Fatal("json enc")
	}

	// geometry point
	ep := (&pointType{}).WithEncoding(val.GeomAddrEnc)
	if PreserveAdaptiveEncoding(ep, &pointType{}).Encoding() != val.GeomAddrEnc {
		t.Fatal("point enc")
	}

	// different geometry families -> fresh unchanged (adaptive default)
	freshLine := &linestringType{}
	if PreserveAdaptiveEncoding(ep, freshLine) != freshLine {
		t.Fatal("point->line should be unchanged")
	}

	// different string families varString -> blobString
	evs := &varStringType{sqlStringType: gmstypes.MustCreateStringWithDefaults(1, 255)}
	if PreserveAdaptiveEncoding(evs, freshLong) != freshLong {
		t.Fatal("varchar->text should be unchanged")
	}

	// integer -> fresh unchanged
	if PreserveAdaptiveEncoding(Int64Type, Int64Type) != Int64Type {
		t.Fatal("int unchanged")
	}
}
